import * as fs from 'fs';
import * as path from 'path';
import * as os from 'os';
import * as crypto from 'crypto';
import * as http from 'http';

interface RateLimitState {
  tokens: number;
  lastRefill: number;
  maxTokens: number;
  refillRate: number;
}

interface RetryConfig {
  maxRetries: number;
  baseDelay: number;
  maxDelay: number;
}

class ProxyCache {
  private cacheDir: string;
  private sessionId: string;

  constructor() {
    this.sessionId = crypto.randomBytes(16).toString('hex');
    this.cacheDir = path.join(os.tmpdir(), 'proxy-cache');
    this.ensureCacheDir();
  }

  private ensureCacheDir(): void {
    if (!fs.existsSync(this.cacheDir)) {
      fs.mkdirSync(this.cacheDir, { recursive: true, mode: 0o700 });
    }
  }

  getCachePath(requestId: string): string {
    const sanitized = requestId.replace(/[^a-zA-Z0-9_-]/g, '_');
    const filename = `${this.sessionId}_${sanitized}.tmp`;
    return path.join(this.cacheDir, filename);
  }

  writeResponse(requestId: string, data: Buffer): string {
    const cachePath = this.getCachePath(requestId);
    const fd = fs.openSync(cachePath, fs.constants.O_WRONLY | fs.constants.O_CREAT | fs.constants.O_EXCL, 0o600);
    fs.writeSync(fd, data);
    fs.closeSync(fd);
    return cachePath;
  }

  readResponse(requestId: string): Buffer | null {
    const cachePath = this.getCachePath(requestId);
    if (fs.existsSync(cachePath)) {
      return fs.readFileSync(cachePath);
    }
    return null;
  }
}

class SpilloverBuffer {
  private bufferDir: string;
  private counter: number = 0;

  constructor() {
    this.bufferDir = fs.mkdtempSync(path.join(os.tmpdir(), 'proxy-spillover-'));
  }

  spillToDisk(data: Buffer): string {
    const seqNum = this.counter++;
    const timestamp = Date.now();
    const uniquePart = crypto.randomBytes(8).toString('hex');
    const filename = `spill_${timestamp}_${seqNum}_${uniquePart}`;
    const filepath = path.join(this.bufferDir, filename);
    const fd = fs.openSync(filepath, fs.constants.O_WRONLY | fs.constants.O_CREAT | fs.constants.O_EXCL, 0o600);
    fs.writeSync(fd, data);
    fs.closeSync(fd);
    return filepath;
  }

  reclaim(filepath: string): Buffer {
    const resolved = path.resolve(filepath);
    if (!resolved.startsWith(this.bufferDir)) {
      throw new Error('Invalid spillover path');
    }
    const data = fs.readFileSync(resolved);
    fs.unlinkSync(resolved);
    return data;
  }
}

class RateLimiter {
  private state: RateLimitState;

  constructor(maxTokens: number = 100, refillRate: number = 10) {
    this.state = {
      tokens: maxTokens,
      lastRefill: Date.now(),
      maxTokens,
      refillRate
    };
  }

  tryConsume(): boolean {
    this.refill();
    if (this.state.tokens > 0) {
      this.state.tokens--;
      return true;
    }
    return false;
  }

  private refill(): void {
    const now = Date.now();
    const elapsed = (now - this.state.lastRefill) / 1000;
    const newTokens = elapsed * this.state.refillRate;
    this.state.tokens = Math.min(this.state.maxTokens, this.state.tokens + newTokens);
    this.state.lastRefill = now;
  }
}

class NetworkProxy {
  private rateLimiter: RateLimiter;
  private retryConfig: RetryConfig;
  private cache: ProxyCache;
  private spillover: SpilloverBuffer;
  private pendingRetries: Map<string, { attempts: number; lastAttempt: number }>;

  constructor(retryConfig?: Partial<RetryConfig>) {
    this.rateLimiter = new RateLimiter();
    this.retryConfig = {
      maxRetries: retryConfig?.maxRetries ?? 3,
      baseDelay: retryConfig?.baseDelay ?? 1000,
      maxDelay: retryConfig?.maxDelay ?? 30000
    };
    this.cache = new ProxyCache();
    this.spillover = new SpilloverBuffer();
    this.pendingRetries = new Map();
  }

  async proxyRequest(targetUrl: string, body?: Buffer): Promise<Buffer> {
    const requestId = crypto.createHash('sha256').update(targetUrl).digest('hex').slice(0, 16);

    const cached = this.cache.readResponse(requestId);
    if (cached) return cached;

    let spillPath: string | null = null;
    if (body && body.length > 1024 * 1024) {
      spillPath = this.spillover.spillToDisk(body);
    }

    for (let attempt = 0; attempt <= this.retryConfig.maxRetries; attempt++) {
      if (!this.rateLimiter.tryConsume()) {
        const delay = this.calculateBackoff(attempt);
        await this.sleep(delay);
        continue;
      }

      try {
        const requestBody = spillPath ? this.spillover.reclaim(spillPath) : body;
        const response = await this.makeRequest(targetUrl, requestBody);
        this.cache.writeResponse(requestId, response);
        return response;
      } catch (err) {
        this.pendingRetries.set(requestId, { attempts: attempt + 1, lastAttempt: Date.now() });
        if (attempt === this.retryConfig.maxRetries) {
          if (spillPath && fs.existsSync(spillPath)) fs.unlinkSync(spillPath);
          throw err;
        }
        const delay = this.calculateBackoff(attempt);
        await this.sleep(delay);
      }
    }
    throw new Error('Exhausted retries');
  }

  private calculateBackoff(attempt: number): number {
    const delay = this.retryConfig.baseDelay * Math.pow(2, attempt);
    const jitter = Math.random() * delay * 0.1;
    return Math.min(delay + jitter, this.retryConfig.maxDelay);
  }

  private makeRequest(url: string, body?: Buffer): Promise<Buffer> {
    return new Promise((resolve, reject) => {
      const req = http.request(url, { method: body ? 'POST' : 'GET' }, (res) => {
        const chunks: Buffer[] = [];
        res.on('data', (chunk) => chunks.push(chunk));
        res.on('end', () => resolve(Buffer.concat(chunks)));
      });
      req.on('error', reject);
      if (body) req.write(body);
      req.end();
    });
  }

  private sleep(ms: number): Promise<void> {
    return new Promise(resolve => setTimeout(resolve, ms));
  }
}

export { NetworkProxy, RateLimiter, ProxyCache, SpilloverBuffer };
